BEGIN;
CREATE TEMP TABLE operational_checks(name text,passed boolean);
DO $$
DECLARE s uuid; other_s uuid; p uuid; oid uuid; created jsonb; reserved jsonb; stamp timestamptz; rejected boolean; result jsonb;
BEGIN
 INSERT INTO public.sellers(user_id,store_username,store_name) VALUES('TEST-ops-'||gen_random_uuid(),'verify_ops_'||substr(gen_random_uuid()::text,1,8),'TEST operations') RETURNING id INTO s;
 INSERT INTO public.sellers(user_id,store_username,store_name) VALUES('TEST-other-ops-'||gen_random_uuid(),'verify_other_'||substr(gen_random_uuid()::text,1,8),'TEST other') RETURNING id INTO other_s;
 created:=public.publish_catalog_product(s,'{"title":"TEST last unit","price":100,"stock":1,"currency":"MXN","images":[],"delivery_options":["meetup"],"catalog_visible":false}','[]','TESTOPS001');p:=(created->'product'->>'id')::uuid;
 reserved:=public.reserve_purchase(created->'link'->>'public_id','RF-OPSTEST',repeat('a',64),'TEST buyer','test@example.com','555','{}','meetup');
 oid:=(reserved->>'id')::uuid;
 INSERT INTO operational_checks VALUES('last unit reserved',(SELECT stock FROM products WHERE id=p)=0);
 rejected:=false;
 BEGIN PERFORM public.reserve_purchase(created->'link'->>'public_id','RF-OPSTEST2',repeat('b',64),'TEST','test@example.com','555','{}','meetup');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('second purchase cannot oversell',rejected AND (SELECT stock FROM products WHERE id=p)=0);
 SELECT updated_at INTO stamp FROM products WHERE id=p;
 PERFORM public.edit_catalog_details(s,p,stamp,'{"title":"Updated TEST","description":"Changed","price":200,"images":["https://example.com/photo.png"],"variants":[]}');
 INSERT INTO operational_checks VALUES('purchase snapshot unchanged',(SELECT title='TEST last unit' AND unit_price=100 AND line_total=100 FROM order_items WHERE order_id=oid) AND (SELECT stock=0 AND price=200 AND image_url='https://example.com/photo.png' FROM products WHERE id=p));
 rejected:=false;BEGIN PERFORM public.edit_catalog_details(s,p,stamp-interval '1 second','{"title":"Stale","description":"","price":1,"images":[],"variants":[]}');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('stale edit rejected',rejected);
 INSERT INTO operational_checks VALUES('foreign seller cannot edit',NOT public.edit_catalog_details(other_s,p,stamp,'{}'));
 PERFORM public.cancel_unpaid_purchase(oid,'TEST cleanup');PERFORM public.cancel_unpaid_purchase(oid,'TEST duplicate');
 INSERT INTO operational_checks VALUES('duplicate cancellation restores once',(SELECT stock FROM products WHERE id=p)=1);
 UPDATE orders SET payment_status='SUCCEEDED',status='PAID',paid_at=now() WHERE id=oid;
 result:=public.change_delivery_arrangement(oid,s,'seller','propose',0,'TEST public meeting',now()+interval '1 day');
 INSERT INTO operational_checks VALUES('proposal is not confirmation',result->>'status'='PROPOSED');
 rejected:=false;BEGIN PERFORM public.change_delivery_arrangement(oid,s,'seller','confirm',1);EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('proposer cannot self-confirm',rejected);
 result:=public.change_delivery_arrangement(oid,s,'buyer','confirm',1);
 INSERT INTO operational_checks VALUES('other party confirms',result->>'status'='CONFIRMED' AND (result->>'version')::int=2);
 rejected:=false;BEGIN PERFORM public.change_delivery_arrangement(oid,s,'buyer','propose',1,'TEST stale proposal',now()+interval '1 day');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('stale proposal rejected',rejected);
 rejected:=false;BEGIN PERFORM public.change_delivery_arrangement(oid,other_s,'seller','propose',2,'TEST foreign',now()+interval '1 day');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('foreign seller cannot coordinate',rejected);
 UPDATE delivery_arrangements SET scheduled_at=now()-interval '1 minute' WHERE order_id=oid;
 result:=public.change_delivery_arrangement(oid,s,'buyer','missed',2);
 INSERT INTO operational_checks VALUES('missed appointment does not complete order',result->>'status'='MISSED' AND (SELECT status='PAID' FROM orders WHERE id=oid));
 INSERT INTO operational_checks VALUES('history retained',(SELECT count(*) FROM operational_activity WHERE order_id=oid)=3 AND (SELECT count(*) FROM operational_activity WHERE product_id=p)=1);
 UPDATE orders SET status='COMPLETED' WHERE id=oid;
 rejected:=false;BEGIN PERFORM public.change_delivery_arrangement(oid,s,'seller','propose',3,'TEST finished',now()+interval '1 day');EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 INSERT INTO operational_checks VALUES('completed order cannot renegotiate',rejected);
 IF EXISTS(SELECT 1 FROM operational_checks WHERE NOT passed OR passed IS NULL) THEN RAISE EXCEPTION 'Operational verification failed';END IF;
END $$;
SELECT * FROM operational_checks;
ROLLBACK;
